    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;Select c.Id,NumarStatPlata,c.Marca,s.Nume,AnReferintaCO,c.MediaZiSalariu,Avans,\nDatadeInceput,DatadeSfarsit,c.ZileCO,\n--primul interval\nInterval1DatadeInceput,Interval1DatadeSfarsit,NrZileCO1,BazaCalcul1,AvansCO1,\n--al doilea interval\nInterval2DatadeInceput,Interval2DatadeSfarsit,NrZileCO2,BazaCalcul2,AvansCO2,\n--al treilea interval\nInterval3DatadeInceput,Interval3DatadeSfarsit,NrZileCO3,BazaCalcul3,AvansCO3,\n--prima de vacanta\nPrimaVacanta,PrimaVacantaBC,PrimaVacantaImpozit,\nc.CreatedDate,c.CreatedBy,c.LastModifiedDate,c.LastModifiedDate,c.Status,sca.Badge\nfrom app.ConcediudeOdihna c\nJOIN app.Salariat s on s.marca=c.marca\nLEFT JOIN app.StatusCalcul sca\n  ON ISNULL(c.Status, 1) = sca.Id \nwhere ((year(Interval1DatadeInceput)=@Anul and month((Interval1DatadeInceput))=@Luna)\nor (year(Interval2DatadeInceput)=@Anul and month((Interval2DatadeInceput))=@Luna)\nor (year(Interval3DatadeInceput)=@Anul and month((Interval3DatadeInceput))=@Luna))\nand c.CodSucursala=@CodSucursala \norder by c.Marca,DatadeInceput &quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;OrderBy&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fiel